<?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="editor-form" data-section="<?=h($key)?>"><?=csrfField()?>
<div class="two-cols"><?php foreach(['ru'=>'Русский','en'=>'English'] as $locale=>$label):?><section><h2><?=$label?></h2><label><?=t('Заголовок','Title')?><input name="title_<?=$locale?>" required maxlength="180" value="<?=h($row['title_'.$locale]??'')?>"></label><label for="body_<?=$locale?>"><?=t('Содержание','Content')?></label><textarea class="rich-editor" id="body_<?=$locale?>" name="body_<?=$locale?>" rows="12"><?=h($row['body_'.$locale]??'')?></textarea></section><?php endforeach;?></div>
