<?php if($key==='subtypes'):?><label><?=t('Тип мебели','Furniture type')?><select name="type_id" required><option value=""><?=t('Выберите','Select')?></option><?php foreach(Content::all('types') as $parent):?><option value="<?=$parent['id']?>" <?=($row['type_id']??0)==$parent['id']?'selected':''?>><?=h(tr($parent))?></option><?php endforeach;?></select></label><?php endif;?>
<?php if($key==='products'):?><label><?=t('Подтип мебели','Furniture subtype')?><select name="subtype_id" required><option value=""><?=t('Выберите','Select')?></option><?php foreach(Content::all('subtypes') as $parent):?><option value="<?=$parent['id']?>" <?=($row['subtype_id']??0)==$parent['id']?'selected':''?>><?=h(tr($parent))?></option><?php endforeach;?></select></label><label><?=t('Дизайнер','Designer')?><select name="designer_id"><option value=""><?=t('Без привязки','Not assigned')?></option><?php foreach(Content::all('designers') as $parent):?><option value="<?=$parent['id']?>" <?=($row['designer_id']??0)==$parent['id']?'selected':''?>><?=h(tr($parent))?></option><?php endforeach;?></select></label><label><?=t('Цена, руб.','Price, RUB')?><input name="price" type="number" min="0.01" max="9999999.99" step="0.01" required value="<?=h($row['price']??(isset($row['price_minor'])?number_format((int)$row['price_minor']/100,2,'.',''):''))?>"></label><?php endif;?><label><?=t('Порядок','Sort order')?><input type="number" name="sort_order" required min="-10000" max="10000" value="<?=h($row['sort_order']??0)?>"></label><label class="check"><input type="checkbox" name="published" value="1" <?=($row['published']??($id?0:1))?'checked':''?>> <?=t('Опубликовать','Publish')?></label></section><section><label><?=t('Обложка JPG, PNG, WebP до 4 МБ','Cover JPG, PNG, WebP up to 4 MB')?><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php if(!empty($row['image'])):?><img class="admin-preview" src="<?=h($row['image'])?>" alt="<?=t('Текущая обложка','Current cover')?>"><?php endif;?><?php if(in_array($key,['types','products'],true)):?><label><?=t('Фото для слайдшоу, до 10 за раз','Slideshow photos, up to 10 at a time')?><input type="file" name="gallery[]" multiple accept="image/jpeg,image/png,image/webp"></label><?php endif;?><p class="small"><?=t('Для изображения внутри текста используйте кнопку изображения в редакторе → Upload.','To insert an inline image, use the editor image button → Upload.')?></p></section></div><p><button class="button"><?=t('Сохранить','Save')?></button> <a href="/admin/content/<?=h($key)?>"><?=t('Отмена','Cancel')?></a></p></form>
<?php if($id&&in_array($key,['types','products'],true)):?><h2><?=t('Галерея','Gallery')?></h2><div class="gallery-admin"><?php foreach(Catalog::images($key,$id) as $photo):?><div><img src="<?=h($photo['path'])?>" alt="<?=t('Фотография галереи','Gallery photo')?>"><form method="post" action="/admin/gallery/<?=h($key)?>/<?=$id?>/<?=$photo['id']?>/delete" data-confirm><?=csrfField()?><button><?=t('Удалить фото','Delete photo')?></button></form></div><?php endforeach;?></div><?php endif;?>
